const definitionDialog=document.createElement('dialog');definitionDialog.className='definition-dialog';definitionDialog.setAttribute('aria-label','Concept definition');document.body.append(definitionDialog);
function openDefinition(id,origin){const entry=findReference(id);if(!entry)return;if(!definitionDialog.open){definitionOrigin=origin;definitionScroll=window.scrollY;}definitionDialog.innerHTML=definitionBody(entry)+'<div class="dialog-actions"><a class="button secondary" href="#glossary:'+entry.id+'" data-definition-link>Full reference entry →</a><button type="button" class="button" data-close-definition>Return to my work</button></div>';if(!definitionDialog.open)definitionDialog.showModal();definitionDialog.querySelector('[data-close-definition]').focus();animateInteraction(definitionDialog);}
function closeDefinition(){if(definitionDialog.open)definitionDialog.close();}
definitionDialog.addEventListener('close',()=>{definitionOrigin?.focus({preventScroll:true});window.scrollTo(0,definitionScroll);});
definitionDialog.addEventListener('click',ev=>{const target=ev.target.closest('[data-action="define"]');if(target)openDefinition(target.dataset.term,target);if(ev.target.closest('[data-close-definition]'))closeDefinition();if(ev.target.closest('[data-definition-link]'))closeDefinition();});
app.addEventListener('click',ev=>{const anchor=ev.target.closest('[data-local-anchor]');if(!anchor)return;ev.preventDefault();const target=document.getElementById(anchor.getAttribute('href').slice(1));if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView(scrollOptions());}});
