const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const pct=v=>`${v}%`;
const link=(route,label,cls='')=>`<a class="${cls}" href="#${route}">${label}</a>`;
const button=(action,label,extra='',cls='button')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const title=(eyebrow,heading,description,action='')=>`<div class="page-title"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p class="subtitle">${description}</p></div>${action}</div>`;
const cardPatterns={'The concept':'concept-notebook concept-summary','Make the consulting decision':'decision-workspace','Practical assignment':'practice-workspace','Skill evidence':'skill-evidence','Client brief':'client-dossier','Sample document':'document-specimen','Discovery room':'discovery-session','Your consulting recommendation':'decision-workspace','Build the future-state workflow':'workflow-studio','Current state to improve':'map-context','Incident log':'incident-log','Your recovery plan':'recovery-workspace','Business assumptions':'assumption-sheet','Estimated outcome':'business-outcome','The assignment':'engagement-brief','The assessment standard':'assessment-standard'};
const card=(heading,body,cls='')=>`<section id="${heading==='Make the consulting decision'?'lesson-decisions':heading==='Practical assignment'?'lesson-assignment':'section-'+heading.toLowerCase().replace(/[^a-z0-9]+/g,'-')}" class="card ${cardPatterns[heading]||''} ${cls}"><h2>${cardPatterns[heading]==='decision-workspace'?icon('decision'):''}${heading}</h2>${body}</section>`;
function save(){storageError=saveProgress(state);const status=document.querySelector('#save-status');if(status)status.textContent=storageError?'Saving unavailable':'Saved on this device';if(storageError)toast(storageError);}
let toastTimer;
function toast(msg){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),6000);}
let exportURL=null;
function closeExport(){document.querySelector('#export-panel')?.remove();if(exportURL)URL.revokeObjectURL(exportURL);exportURL=null;}
function download(name,text,type='text/markdown'){
  closeExport();exportURL=URL.createObjectURL(new Blob([text],{type}));
  const panel=document.createElement('section');panel.id='export-panel';panel.className='card export-panel';panel.setAttribute('aria-label','Prepared file export');
  panel.innerHTML=`<div class="section-heading"><h2>File ready: ${e(name)}</h2><button type="button" class="icon-button" aria-label="Close export">×</button></div><p>Use Save file to download. If your embedded browser blocks downloads, select the contents below and save them in a local text file with the displayed filename.</p><a class="button" download="${e(name)}">Save file</a><label class="field"><span>Export contents</span><textarea readonly rows="5"></textarea></label>`;
  panel.querySelector('a').href=exportURL;panel.querySelector('textarea').value=text;panel.querySelector('button').addEventListener('click',closeExport);document.body.append(panel);panel.querySelector('a').click();panel.querySelector('a').focus();
}
function field(label,key,value,type='text',hint='',extra='') {const id='field-'+key.replaceAll('.','-');return `<label class="field" for="${id}"><span>${label}</span><input id="${id}" type="${type}" data-field="${key}" value="${e(value)}" ${type==='number'?'min="0" max="1000000000" step="any"':''} ${extra}>${hint?`<small>${hint}</small>`:''}</label>`;}
function area(label,key,value,hint='',extra=''){const id='field-'+key.replaceAll('.','-');return `<label class="field" for="${id}"><span>${e(label)}</span>${hint?`<small>${e(hint)}</small>`:''}<textarea id="${id}" data-field="${key}" rows="4" ${extra}>${e(value)}</textarea></label>`;}
function select(label,key,value,options,hint=''){const id='field-'+key.replaceAll('.','-');return `<label class="field" for="${id}"><span>${e(label)}</span><select id="${id}" data-field="${key}" required><option value="">Choose an answer</option>${options.map(([v,t])=>`<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`).join('')}</select>${hint?`<small>${e(hint)}</small>`:''}</label>`;}
function feedback(result,scope=currentRoute()){return decisionReview(result,scope);}
function attemptReport(key){const r=assessmentSummary(state,key);return r.assessed?'<p class="notice">First '+r.first.score+'/100 · Latest '+r.latest.score+'/100 · Best practice '+r.best+'/100 · Evidence '+r.evidenceScore+'/100 · '+r.count+' attempts. Evidence averages first and latest; retries never erase the first attempt or add new evidence sources.</p>':'';}
function questions(bank,path,answers,prefix){return bank.map((q,i)=>'<fieldset class="assessment-question"><legend><span class="question-index">'+String(i+1).padStart(2,'0')+'</span>'+e(q.prompt)+'</legend>'+q.options.map((o,j)=>'<label class="choice"><input type="radio" name="'+prefix+'-'+i+'" value="'+j+'" data-field="'+path+'.'+i+'" '+(String(answers[i])===String(j)?'checked':'')+' required><span>'+e(o)+'</span></label>').join('')+'</fieldset>').join('');}
function currentRoute(){return entryPending?'entry':location.hash.slice(1)||'dashboard';}
const navItems=[['dashboard','◫','Overview'],['start','↗','AI Start Here'],['course','▤','Learning path'],['cases','◇','Client engagements'],['map','⇄','Workflow lab'],['opportunity','▥','Opportunity lab'],['roi','$','ROI workbench'],['capstone','⚑','Capstone'],['scores','◎','Competency report'],['resources','▧','Resources'],['glossary','Aa','Glossary'],['mentor','◌','Local mentor']];
