function resourceResults(){const filtered=resources.filter(r=>r.join(' ').toLowerCase().includes(query.toLowerCase()));return filtered.length?filtered.map(r=>`<section class="card resource"><span class="eyebrow">CONSULTING TEMPLATE</span><h2>${e(r[0])}</h2><p>${e(r[2])}</p><details><summary>Preview template</summary><pre>${e(r[1])}</pre></details>${button('resource','Download template',`data-id="${resources.indexOf(r)}"`,'button secondary')}</section>`).join(''):'<div class="empty"><h2>No matching resources</h2><p>Try “risk”, “pilot” or “discovery”.</p></div>';}
