function mentorView(){return title('LOCAL BUSINESS MENTOR','Pressure-test your thinking','Predefined coaching prompts that challenge assumptions. No model is connected; this mentor does not grade your work.')+card('Bring a business question',`<div class="mentor-messages" aria-live="polite">${mentorHistory.length?mentorHistory.map(m=>`<div class="reply ${m.role==='You'?'user-reply':''}"><span>${e(m.role)}</span><p>${e(m.text)}</p></div>`).join(''):'<div class="empty"><h3>What would you validate before building?</h3><p>Ask about discovery, ROI, agents, data risk or workflow design.</p></div>'}</div><form data-submit="mentor"><label class="field"><span>Your question</span><textarea name="message" rows="3" maxlength="2000" required placeholder="For example: should this purchasing workflow use an agent?"></textarea></label><button type="submit" class="button">Get a coaching question →</button></form>`);}
function settingsView(){return card('Motion preference','<p>System reduced-motion preferences always take priority. You can also use a fully static experience here; all content and controls remain available.</p>'+button('static-motion',state.experience.staticMotion?'Static experience enabled · enable motion':'Motion enabled · use static experience','aria-pressed="'+state.experience.staticMotion+'"','button secondary'))+title('LOCAL DATA','Your progress stays on this device','No accounts, telemetry or remote storage. Browser clearing or a different browser can lose progress; keep a backup.')+card('Back up and restore',`<p>Export lessons, interview progress, notes, maps, ROI and capstone drafts to a local JSON file. Restoring replaces the current progress after validation.</p><div class="actions">${button('backup','Export JSON backup')}<label class="button secondary file-label">Choose backup to restore<input type="file" id="import-file" accept="application/json,.json"></label></div><p class="fine">Do not store real customer, employee or financial information in this training app. The browser storage is local and not encrypted.</p><div id="import-review"></div>`)+(state.legacy.revision?card('Previous edition archive','<p>Preserved original attempts, case recommendations, maps and capstone work from edition '+e(state.legacy.revision)+'. Revised assessment evidence is separate.</p><details><summary>Inspect preserved work</summary><pre>'+e(JSON.stringify(state.legacy,null,2))+'</pre></details>'):'')+card('Start Fresh','<p>This removes course progress from this browser only. Export a backup first if you want to keep your work.</p>'+button('reset-confirm','Start Fresh','','button danger')+'<div id="reset-review"></div>')+(testingUtility()?card('Testing utilities','<p>Local development only. Create a clean learner profile for acceptance testing; interface preferences remain.</p>'+button('reset-confirm','Create clean test learner','','button secondary')):'');}
function setPath(path,value){const parts=path.split('.');let obj=state;for(let i=0;i<parts.length-1;i++){const k=parts[i];if(!Object.hasOwn(obj,k)||obj[k]==null)obj[k]=/^\d+$/.test(parts[i+1])?[]:{};obj=obj[k];}obj[parts.at(-1)]=value;}
app.addEventListener('input',ev=>{const input=ev.target;const key=input.dataset.field;if(!key)return;if(key.startsWith('search.')){query=input.value;referenceLimit=24;const kind=key.split('.')[1];document.querySelector('#'+(kind==='resources'?'resource':'glossary')+'-results').innerHTML=kind==='resources'?resourceResults():glossaryResults();return;}setPath(key,input.value);updateDraftStates();if(key.startsWith('experience.visuals.')){const [, ,kind]=key.split('.'),panel=input.closest('[data-visual-lab]');panel.querySelector('.visual-outcome').innerHTML=outcomeView(kind,state.experience.visuals[kind]);animateInteraction(panel.querySelector('.visual-outcome'));save();return;}if(key.startsWith('experience.')){const p=key.split('.')[1];if(p==='starter'){state.experience.starter[key.split('.')[2]].submitted=false;}else if(['classification','conversation'].includes(p))state.experience[p].submitted=false;input.closest('.card')?.querySelector('.feedback')?.remove();}if(key.startsWith('map.owners.')){const row=input.closest('li');row.className=mapType(input.value);row.querySelector('.node-type').innerHTML=icon(mapType(input.value).slice(5))+e(mapLabel(input.value));}if(input.type==='radio'){input.closest('fieldset')?.querySelectorAll('.choice-state').forEach(x=>x.remove());input.closest('fieldset')?.querySelectorAll('.choice').forEach(x=>x.classList.remove('assessed-correct','assessed-incorrect'));}const parts=key.split('.');const assessment=parts[0]==='cases'?state.cases[parts[1]]:['map','opportunity','failure','capstone'].includes(parts[0])?state[parts[0]]:null;if(assessment?.submitted){assessment.submitted=false;document.querySelector('.feedback')?.remove();toast('Draft changed. Submit again to update your score.');}updateDraftStates();save();if(key.startsWith('roi.'))updateROI();if(key.startsWith('opportunity.'))updateOpportunity();if(key.startsWith('capstone.')){const k=key.split('.')[1];const el=document.querySelector('#draft-'+k);if(el)el.textContent=input.value.trim().length>=80?'Drafted':'To draft';const drafted=capstoneSections.filter(([id])=>(state.capstone[id]||'').trim().length>=80).length;document.querySelector('#capstone-draft-count').textContent=drafted+'/15 deliverables drafted.';document.querySelector('#capstone-draft-progress').value=drafted;updateProgress(app,currentRoute());}});
app.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,kind=form.dataset.submit,id=form.dataset.id;if(!kind)return;
  if(kind==='starter'){const unit=starterUnits.find(x=>x.id===id);const answer=form.querySelector('[name="starter"]:checked')?.value;if(!unit||answer===undefined)return;state.experience.starter[id]={answer,submitted:true};
  }else if(kind==='classification'){state.experience.classification.submitted=true;
  }else if(kind==='conversation'){state.experience.conversation.submitted=true;
  }else if(kind==='assignment'){const d=state.assignments[id]||{};const result=gradePractice(id,d);if(!result.complete){toast('Complete all nine fields before submitting.');return;}if((d.decisions||[]).length<2){toast('Answer both applied decisions.');return;}recordAttempt(state,'assignment:'+id,d);
  }else if(kind==='consequence'){const incident=state.consequences[id][Number(form.dataset.index)],c=cases.find(x=>x.id===id);if(!incident.answer){toast('Choose a recovery diagnosis.');return;}const result=gradeConsequence(c,incident,incident.answer);incident.history.push({answer:incident.answer,at:new Date().toISOString()});incident.recovered=result.passed;
  }else if(kind==='lesson'){const l=lessons.find(l=>l.id===id);const answers=l.questions.map((_,i)=>form.querySelector(`[name="question-${i}"]:checked`)?.value);if(answers.some(x=>x===undefined)){toast('Answer every decision before submitting.');return;}recordAttempt(state,'lesson:'+id,{answers});const score=gradeLesson(l,answers).score;const old=state.lessons[id]||{};state.lessons[id]={...old,answers,lastAnswers:answers,draft:answers,score:Math.max(old.score||0,score),latestScore:score,attempts:(old.attempts||0)+1,at:new Date().toISOString()}; // Best practice cache is separate from the immutable assessment ledger.
    if(score<(old.score||0)){state.lessons[id].answers=old.answers;toast('Your best demonstrated result is retained. Review the latest choices before retrying.');}
  }else if(kind==='case'){const c=cases.find(x=>x.id===id),d=state.cases[id]||{},asked=state.interviews[id]?.asked||[];if((state.consequences[id]||[]).some(x=>!x.recovered)){toast('Diagnose the pending consequence first.');return;}if(!['systems','time','exceptions','risk'].every(x=>asked.includes(x))||c.assessed.some(q=>!d[q.id])){toast('Complete discovery and all eight decisions.');return;}recordAttempt(state,'case:'+id,d,{asked});const incident=newConsequence(c,d);if(incident)(state.consequences[id]||=[]).push(incident);state.cases[id]={...d,submitted:true};}
  else if(['map','opportunity','failure','capstone'].includes(kind)){recordAttempt(state,kind,state[kind],kind==='capstone'?{solarDraft:state.cases.solar||{},solarAsked:state.interviews.solar?.asked||[],map:state.map,roi:state.roi}:{});state[kind].submitted=true;}
  else if(kind==='mentor'){const message=form.elements.message.value.trim();if(!message){toast('Enter a business question.');return;}mentorHistory.push({role:'You',text:message});const reply=await localMentor.reply({message,route:currentRoute()});mentorHistory.push({role:reply.provider,text:reply.text});render();return;}
  const flow=flowState(state),scope=kind==='starter'?'starter:'+id:kind==='conversation'?'conversation:'+(state.experience.conversation.topic||0):kind==='classification'?'classification':kind==='consequence'?'consequence:'+id+'@'+(Number(form.dataset.index)+1):kind==='assignment'?'assignment:'+id:currentRoute();for(const key of Object.keys(flow.reviews||{}))if(key===scope||key.startsWith(scope+'@'))delete flow.reviews[key];if(['case','map','opportunity','failure','capstone'].includes(kind))(flow.activities||={})[currentRoute()]='review';
  revising.delete(kind+':'+id);save();submissionMotion=true;render();const acknowledgement=milestone(state,kind,id);if(acknowledgement){document.querySelector('#main').insertAdjacentHTML('afterbegin',acknowledgement);animateInteraction(document.querySelector('.milestone'));}markSubmittedChoices(form.dataset.submit,id);const result=document.querySelector('form[data-submit="'+kind+'"]')?.closest('.card')?.querySelector('.feedback')||document.querySelector('.feedback');if(result){result.setAttribute('tabindex','-1');result.focus();result.scrollIntoView(scrollOptions());}toast(['starter','classification','conversation'].includes(kind)?'Guided practice saved. Competency scores are unchanged.':'Assessment saved. Review the evidence and next steps.');
});
let pendingImport=null;
app.addEventListener('change',async ev=>{if(ev.target.dataset.action==='reference-category'){referenceCategory=ev.target.value;referenceLimit=24;document.querySelector('#glossary-results').innerHTML=glossaryResults();return;}if(ev.target.dataset.action==='owner-topic'){state.experience.conversation={...state.experience.conversation,topic:ev.target.value,answer:'',submitted:false};save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector('[data-action="owner-topic"]').focus();return;}if(ev.target.id!=='import-file')return;try{const file=ev.target.files[0];if(!file)return;if(file.size>2_000_000)throw new Error('Backup is too large (limit 2 MB).');pendingImport=validateBackup(JSON.parse(await file.text()));document.querySelector('#import-review').innerHTML=`<div class="notice warning">Valid progress backup; earlier work preserved. Restoring replaces this browser’s current progress.</div>${button('restore','Restore this backup')}`;}catch(err){pendingImport=null;document.querySelector('#import-review').textContent='Backup rejected: '+err.message;}});
app.addEventListener('click',ev=>{if(ev.target.closest('.skip')){ev.preventDefault();document.querySelector('#main').focus();return;}const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
  if(a==='revise'){const form=b.closest('form'),key=form.dataset.submit+':'+form.dataset.id;revising.add(key);form.querySelectorAll('fieldset').forEach(x=>x.disabled=false);form.querySelector('[type="submit"]').disabled=false;b.remove();form.querySelectorAll('.assessed-correct,.assessed-incorrect').forEach(x=>x.classList.remove('assessed-correct','assessed-incorrect'));form.querySelectorAll('.choice-state').forEach(x=>x.remove());updateDraftStates();form.querySelector('input:checked')?.focus();toast('Revise your decisions, then submit a new attempt. Earlier evidence is retained.');return;}
  if(a==='define'){openDefinition(b.dataset.term,b);return;}
  if(a==='reference-more'){referenceLimit+=24;document.querySelector('#glossary-results').innerHTML=glossaryResults(currentRoute().split(':')[1]);return;}
  if(a==='static-motion'){state.experience.staticMotion=!state.experience.staticMotion;configureMotion(state.experience.staticMotion);save();render();document.querySelector('[data-action="static-motion"]')?.focus();return;}
  if(a==='menu'){menuOpen=!menuOpen;render();}
  if(a==='ask'){const id=b.dataset.case,q=b.dataset.question;if(!discoveryAvailable(cases.find(x=>x.id===id),state.interviews[id]?.asked||[]).find(x=>x.id===q)?.available)return;state.interviews[id]||={asked:[]};if(!state.interviews[id].asked.includes(q))state.interviews[id].asked.push(q);save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-question="${q}"]`)?.focus();toast('Evidence collected from '+cases.find(c=>c.id===id).questions.find(x=>x.id===q).role+'. Review the response and discovery notes.');}
  if(a==='move'){const i=Number(b.dataset.index),j=i+Number(b.dataset.direction);if(j<0||j>=state.map.order.length)return;[state.map.order[i],state.map.order[j]]=[state.map.order[j],state.map.order[i]];state.map.submitted=false;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-index="${j}"][data-direction="${b.dataset.direction}"]`)?.focus();animateInteraction(document.querySelector(`[data-index="${j}"]`)?.closest('li'));}
  if(a==='case-roi'){const c=cases.find(c=>c.id===b.dataset.id);state.roi={...state.roi,frequency:c.volume,current:c.baseline,future:c.target,hourly:c.hourly,implementation:c.cost,software:c.monthly,maintenance:0,training:0,api:0,errors:0};save();location.hash='roi';toast('Client estimates loaded. Validate these assumptions and add training and support costs.');}
  if(a==='resource'){const index=Number(b.dataset.id),r=resources[index];download(r[0].toLowerCase().replaceAll(' ','-')+'.md',resourceDocument(index));toast('Template downloaded.');}
  if(a==='backup')download('consultant-progress.json',JSON.stringify(state,null,2),'application/json');
  if(a==='restore'&&pendingImport){state=pendingImport;pendingImport=null;save();render();toast('Backup restored. Scores verified against your submitted work.');}
  if(a==='reset-confirm'){openSessionReset(null,b);return;}
  if(a==='begin-course'){navigateSession('start');return;}
  if(a==='resume-course'){navigateSession(resumeCourseRoute(state));return;}
  if(a==='restart-lesson'){openSessionReset(b.dataset.lesson,b);return;}
  if(a==='hint'){const k=b.dataset.id;document.querySelector('#hint-'+k).textContent='Coaching question: '+({goal:'What measured outcome would the owner accept?',discovery:'Which employee handles exceptions and what recent transaction can they show?',current:'Where does revision information stop being shared?',bottleneck:'What evidence separates missing inputs from slow calculation?',priorities:'Which improvement prevents rework before adding AI?',future:'What should stop when a layout revision changes?',tools:'Which steps need rules and which benefit from language interpretation?',risks:'Who can commit a purchase and what data do they really need?',prototype:'What happens to sample PS-204 when racking family is missing?',roi:'What happens to payback with only 50% realized capacity?',plan:'Who approves the pilot and owns rollback?',presentation:'How would you explain this without naming any AI technology?',objection:'What can go wrong if an unverified quantity is ordered?',training:'Can a buyer demonstrate an exception, not just a normal order?',recommendation:'Who owns monitoring after the project handoff?'}[k]);}
  if(a==='export-capstone')download('solar-capstone.md',capstoneDocument(state));
  if(a==='export-map')download('solar-workflow.md',workflowDocument(state));
  if(a==='export-roi'){try{download('roi-analysis.md',roiDocument(state));}catch(err){toast(err.message);}}
  if(a==='export-case')download(b.dataset.id+'-engagement.md',caseDocument(state,b.dataset.id));
});
const routeTransition=createScreenTransition();
window.addEventListener('hashchange',()=>{closeExport();closeDefinition();menuOpen=false;query='';referenceCategory='';referenceLimit=24;entryPending=false;if(isLearningRoute(currentRoute())){state.lastRoute=currentRoute();save();}routeTransition(document.querySelector('#main'),()=>{render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});},()=>document.querySelector('#main'));});
window.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&menuOpen){menuOpen=false;render();document.querySelector('.menu').focus();}});

function assessmentLabel(key){const [kind,id]=key.split(':');if(kind==='lesson'||kind==='assignment')return (kind==='assignment'?'Applied work · ':'Decision analysis · ')+(lessons.find(l=>l.id===id)?.title||id);if(kind==='case')return 'Client engagement · '+(cases.find(c=>c.id===id)?.name||id);return {map:'Solar workflow map',opportunity:'Opportunity prioritization',failure:'Incident recovery',capstone:'Piedmont Solar capstone'}[key]||key;}
let journeyObserver;
function observeLessonJourney(){journeyObserver?.disconnect();if(!globalThis.IntersectionObserver)return;const links=[...app.querySelectorAll('.lesson-itinerary [data-local-anchor]')];if(!links.length)return;journeyObserver=new IntersectionObserver(entries=>{const visible=entries.filter(x=>x.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(!visible.length)return;for(const link of links){const current=link.getAttribute('href')==='#'+visible[0].target.id;if(current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');}},{rootMargin:'-5% 0px -55% 0px',threshold:0});for(const link of links){const target=document.getElementById(link.getAttribute('href').slice(1));if(target)journeyObserver.observe(target);}}
function updateDraftStates(){for(const form of app.querySelectorAll('form[data-submit]')){const kind=form.dataset.submit;if(['mentor','consequence'].includes(kind))continue;const answered=[...form.querySelectorAll('input[type="radio"]:checked,textarea,select')].some(x=>x.value.trim()!=='');let label=form.querySelector(':scope > .draft-indicator');if(!label){label=document.createElement('p');label.className='draft-indicator';form.prepend(label);}const locked=Boolean(form.querySelector('.revise-control'))||(['case','map','opportunity','failure','capstone'].includes(kind)&&Boolean(kind==='case'?state.cases[form.dataset.id]?.submitted:state[kind]?.submitted));const guided=['starter','classification','conversation'].includes(kind)&&(kind==='starter'?state.experience.starter[form.dataset.id]?.submitted:state.experience[kind]?.submitted);label.textContent=guided?'Guided practice saved · no competency points':locked?'Submitted · review the recorded result':answered?'Draft · saved on this device · submit for review':'Not started · no decisions submitted';}}
function syncAssessmentLocks(){for(const form of document.querySelectorAll('form[data-submit="lesson"],form[data-submit="assignment"]')){const kind=form.dataset.submit,id=form.dataset.id,key=kind+':'+id,record=state.assessments[key]?.history?.at(-1),draft=kind==='lesson'?state.lessons[id]?.draft:state.assignments[id]?.decisions,submitted=kind==='lesson'?record?.payload.answers:record?.payload.decisions;if(!record||revising.has(key)||JSON.stringify(draft)!==JSON.stringify(submitted))continue;form.querySelectorAll('fieldset').forEach(x=>x.disabled=true);form.querySelector('[type="submit"]').disabled=true;form.insertAdjacentHTML('beforeend',button('revise','Revise decisions for another attempt','','button secondary revise-control'));markSubmittedChoices(kind,id);}}
function liveNumber(value,key,display,format='integer',decimals=0){return '<span aria-hidden="true" data-number="'+value+'" data-metric="'+key+'" data-format="'+format+'" data-decimals="'+decimals+'" data-display="'+e(display)+'">'+e(display)+'</span><span class="sr-only">'+e(display)+'</span>';}
function mapLabel(owner){return ({'Approved rules':'Deterministic rules','Material reviewer':'Human approval','Authorized buyer':'Human approval','AI agent':'AI decision',Coordinator:'Human',Buyer:'Human','Project manager':'Human'}[owner]||'Ownership not yet assigned');}
function mapType(owner){return 'type-'+({'Approved rules':'rules','Material reviewer':'approval','Authorized buyer':'approval','AI agent':'ai-decision',Coordinator:'human',Buyer:'human','Project manager':'human'}[owner]||'system');}
function markSubmittedChoices(kind,id){const key=kind==='lesson'?'lesson:'+id:kind==='assignment'?'assignment:'+id:null;if(!key)return;const summary=assessmentSummary(state,key);if(!summary.assessed)return;const selector='form[data-submit="'+kind+'"]';document.querySelectorAll(selector+' fieldset').forEach((fieldset,index)=>{const selected=fieldset.querySelector('input:checked');if(!selected)return;const label=selected.closest('.choice'),correct=summary.latest.feedback[index].correct;label.classList.add(correct?'assessed-correct':'assessed-incorrect');label.querySelector('.choice-state')?.remove();label.querySelector('span').insertAdjacentHTML('beforeend','<small class="choice-state">'+(correct?'✓ Submitted · Correct':'↗ Submitted · Incorrect · Needs revision')+'</small>');});}










function testingUtility(){return ['localhost','127.0.0.1','[::1]'].includes(location.hostname)&&new URLSearchParams(location.search).get('testing')==='1';}
function navigateSession(route){
 entryPending=false;state.lastRoute=route;save();
 if(location.hash.slice(1)!==route){location.hash=route;return;}
 routeTransition(document.querySelector('#main'),()=>{render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});},()=>document.querySelector('#main'));
}
app.addEventListener('click',ev=>{const a=ev.target.closest('a[href^="#"]');if(entryPending&&a){ev.preventDefault();navigateSession(a.getAttribute('href').slice(1));}});
window.addEventListener('storage',ev=>{
 if(ev.key!==STORAGE_KEY||ev.storageArea!==localStorage)return;
 try{state=ev.newValue?validateBackup(JSON.parse(ev.newValue)):freshLearnerState(state);revising.clear();pendingImport=null;mentorHistory=[];clearMotionHistory();entryPending=true;closeDefinition();if(sessionDialog.open)sessionDialog.close();render();toast('The course profile changed in another tab. Choose how to continue.');}catch{toast('Another tab saved unreadable course data. Your current session is retained.');}
});
const sessionDialog=document.createElement('dialog');sessionDialog.className='session-dialog';sessionDialog.setAttribute('aria-labelledby','session-reset-title');document.body.append(sessionDialog);
let resetLessonId=null,resetOrigin=null;
function openSessionReset(lessonId,origin){
resetLessonId=lessonId;resetOrigin=origin;const lesson=lessons.find(l=>l.id===lessonId)||starterUnits.find(u=>'start:'+u.id===lessonId);
 sessionDialog.innerHTML='<p class="eyebrow">'+(lesson?'RESTART THIS CHAPTER':'A NEW LEARNER SESSION')+'</p><h2 id="session-reset-title">'+(lesson?'Restart this lesson?':'Ready for a fresh start?')+'</h2><p>'+(lesson?(lessonId.startsWith('start:')?'This erases this guided recommendation and its lesson position for <b>':'This erases decisions, first-attempt evidence, applied work, notes and stage position for <b>')+e(lesson.title)+'</b>. Your other lessons, client engagements and labs stay saved.':'This erases all course learner progress on this device: assessments and first attempts, assignments, notes, interviews, labs, readiness evidence and capstone drafts.')+'</p><div class="reset-boundary">Interface preferences stay. Your system reduced-motion setting continues to apply.</div><div class="reset-export"></div><p class="reset-error" role="alert"></p><div class="session-dialog-actions"><button type="button" class="button secondary" data-session-export>Export current progress</button><button type="button" class="button secondary" data-session-cancel>Cancel</button><button type="button" class="button danger" data-session-confirm>'+(lesson?'Restart Lesson':'Start fresh')+'</button></div>';
 if(!sessionDialog.open)sessionDialog.showModal();sessionDialog.querySelector('[data-session-cancel]').focus();animateInteraction(sessionDialog);
}
sessionDialog.addEventListener('close',()=>{closeExport();if(resetOrigin?.isConnected)resetOrigin.focus({preventScroll:true});else document.querySelector('#main')?.focus({preventScroll:true});});
sessionDialog.addEventListener('click',ev=>{
 if(ev.target.closest('[data-session-cancel]')){sessionDialog.close();return;}
 if(ev.target.closest('[data-session-export]')){closeExport();exportURL=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const area=sessionDialog.querySelector('.reset-export');area.innerHTML='<p>Your backup is ready. Save it before starting fresh.</p><a class="button secondary" download="consultant-progress.json">Save progress backup</a><details class="backup-fallback"><summary>If this browser blocks downloads</summary><p>Copy these contents into a file named consultant-progress.json. It can be restored from Local data & backups.</p><textarea aria-label="Course backup JSON" readonly rows="4"></textarea><button type="button" class="button secondary" data-session-copy>Copy backup JSON</button><span role="status" data-copy-status></span></details>';area.querySelector('textarea').value=JSON.stringify(state,null,2);area.querySelector('a').href=exportURL;area.querySelector('a').click();area.querySelector('a').focus();return;}
 if(ev.target.closest('[data-session-copy]')){navigator.clipboard.writeText(JSON.stringify(state,null,2)).then(()=>{sessionDialog.querySelector('[data-copy-status]').textContent='Backup copied. Save it as consultant-progress.json.';}).catch(()=>{sessionDialog.querySelector('[data-copy-status]').textContent='Select and copy the backup contents above.';});return;}
 if(ev.target.closest('[data-session-confirm]')){
  const result=persistSessionReset(state,{lessonId:resetLessonId});if(result.error){sessionDialog.querySelector('.reset-error').textContent='Reset could not be saved. Your current progress is retained. '+result.error;return;}
  state=result.state;storageError=null;revising.clear();pendingImport=null;mentorHistory=[];query='';referenceCategory='';referenceLimit=24;menuOpen=false;clearMotionHistory();sessionDialog.close();
  if(resetLessonId){navigateSession(resetLessonId.startsWith('start:')?resetLessonId:'lesson:'+resetLessonId);toast('Lesson restarted. Other course progress is retained.');}
  else{entryPending=true;history.replaceState(null,'',location.pathname+location.search+'#entry');routeTransition(document.querySelector('#main'),()=>{render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});},()=>document.querySelector('#main'));toast('Your fresh learner profile is ready.');}
 }
});

